            Add(translations, "tablet.endgame.doctrineEffects.inactive", "Tier I not reached yet.\nNo doctrine bonus or tradeoff is live.\nProgress this track to activate the posture.", "Palier I pas encore atteint.\nAucun bonus ni compromis de doctrine n'est actif.\nFaites progresser cette voie pour activer la posture.", "Tier I non ancora raggiunto.\nNessun bonus o contropartita è attiva.\nFai avanzare questa traccia per attivare la postura.", "Aún no se alcanzó el nivel I.\nNo hay bono ni contrapartida activa.\nHaz progresar esta ruta para activar la postura.", "Tier I еще не достигнут.\nНи бонус, ни компромисс доктрины не активны.\nПродвигайте эту ветку, чтобы включить позицию.", "Tier I 未達。\nドクトリンのボーナスもトレードオフも未発動。\nこの系統を進めて姿勢を有効化。", "尚未达到 I 级。\n当前没有激活教义加成或代价。\n推进该路线以激活姿态。", "टियर I अभी नहीं पहुँचा।\nकोई डॉक्ट्रिन बोनस या ट्रेडऑफ सक्रिय नहीं है।\nइस ट्रैक को बढ़ाकर रुख सक्रिय करें।", "Tier I ainda não alcançado.\nNenhum bônus ou tradeoff de doutrina está ativo.\nAvance esta trilha para ativar a postura.", "Tier I henüz yok.\nCanlı doktrin bonusu veya ödünleşim yok.\nBu hattı ilerletip duruşu etkinleştir.");
            Add(translations, "tablet.endgame.doctrineEffects.live", "Live bonus: {0}\nLive tradeoff: {1}\n{2}", "Bonus actif : {0}\nCompromis actif : {1}\n{2}", "Bonus attivo: {0}\nContropartita attiva: {1}\n{2}", "Bono activo: {0}\nContrapartida activa: {1}\n{2}", "Активный бонус: {0}\nАктивный компромисс: {1}\n{2}", "有効ボーナス: {0}\n有効トレードオフ: {1}\n{2}", "当前加成：{0}\n当前代价：{1}\n{2}", "सक्रिय बोनस: {0}\nसक्रिय ट्रेडऑफ: {1}\n{2}", "Bônus ativo: {0}\nTradeoff ativo: {1}\n{2}", "Canlı bonus: {0}\nCanlı ödünleşim: {1}\n{2}");
            Add(translations, "tablet.endgame.doctrineEffects.hqOnline", "HQ Online | Capstone boost applied.", "QG en ligne | Bonus de capstone appliqué.", "HQ online | Bonus capstone applicato.", "HQ en línea | Mejora final aplicada.", "HQ в сети | Усиление capstone применено.", "HQ オンライン | 最終ボーナス適用。", "总部在线 | 已应用终局加成。", "HQ ऑनलाइन | कैपस्टोन बूस्ट लागू।", "QG online | Bônus final aplicado.", "HQ çevrimiçi | Zirve güçlendirmesi uygulandı.");
            Add(translations, "tablet.endgame.doctrineEffects.hqOffline", "HQ Offline | Live doctrine active without the capstone boost.", "QG hors ligne | Doctrine active sans bonus final.", "HQ offline | Dottrina attiva senza bonus capstone.", "HQ desconectado | Doctrina activa sin mejora final.", "HQ офлайн | Активная доктрина без capstone-усиления.", "HQ オフライン | 最終ボーナスなしで有効。", "总部离线 | 教义已激活但无终局加成。", "HQ ऑफलाइन | कैपस्टोन बूस्ट बिना सक्रिय सिद्धांत।", "QG offline | Doutrina ativa sem bônus final.", "HQ çevrimdışı | Zirve güçlendirmesi olmadan canlı doktrin aktif.");
            Add(translations, "tablet.endgame.doctrineEffects.potential", "Potential bonus: {0}\nPotential tradeoff: {1}\nBonus not live while another doctrine leads.", "Bonus potentiel : {0}\nCompromis potentiel : {1}\nBonus inactif tant qu'une autre doctrine mène.", "Bonus potenziale: {0}\nContropartita potenziale: {1}\nBonus non attivo finché un'altra dottrina guida.", "Bono potencial: {0}\nContrapartida potencial: {1}\nEl bono no está activo mientras otra doctrina lidera.", "Потенциальный бонус: {0}\nПотенциальный компромисс: {1}\nБонус не действует, пока лидирует другая доктрина.", "潜在ボーナス: {0}\n潜在トレードオフ: {1}\n他のドクトリンが主導中は未発動。", "潜在加成：{0}\n潜在代价：{1}\n当其他教义领先时该加成不会生效。", "संभावित बोनस: {0}\nसंभावित ट्रेडऑफ: {1}\nजब तक कोई और सिद्धांत आगे है बोनस सक्रिय नहीं।", "Bônus potencial: {0}\nTradeoff potencial: {1}\nBônus não fica ativo enquanto outra doutrina lidera.", "Potansiyel bonus: {0}\nPotansiyel ödünleşim: {1}\nBaşka doktrin öndeyken bonus canlı olmaz.");
